/* Independent practice simulator. No D2L services, credentials, or network calls. */
'use strict';
const WORKFLOWS=JSON.parse(document.getElementById('workflow-library').textContent);
const STORAGE_KEY='brightspace-practice-lab-v1';
const clone=x=>JSON.parse(JSON.stringify(x));
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const checked=x=>x?' checked':'';
const selected=(a,b)=>a===b?' selected':'';
const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const pct=x=>x===null||x===undefined?'—':Number(x).toFixed(2)+'%';
const source=(label,url)=>`<a href="${h(url)}" target="_blank" rel="noopener noreferrer">${h(label)} ↗</a>`;
function sampleCourse(id,name,code){return {id,name,code,active:true,start:'',end:'',lessonsOverride:null,
 settings:{mode:'weighted',blanks:'drop',finalType:'calculated',autoRelease:false,autoUpdate:true,finalCanExceed:false,showPoints:true,showPercent:true,decimals:2},
 categories:[{id:'cat-q',name:'Quizzes',weight:40,canExceed:false,dropLowest:0}],
 items:[{id:'q1',name:'Quiz 1',max:10,weight:50,categoryId:'cat-q',bonus:false,canExceed:false,excluded:false,hidden:false},{id:'q2',name:'Quiz 2',max:10,weight:50,categoryId:'cat-q',bonus:false,canExceed:false,excluded:false,hidden:false},{id:'project',name:'Project',max:100,weight:60,categoryId:null,bonus:false,canExceed:false,excluded:false,hidden:false}],
 grades:{u1:{q1:{score:8,exempt:false},q2:{score:6,exempt:false},project:{score:90,exempt:false}},u2:{q1:{score:9,exempt:false},q2:{score:null,exempt:false},project:{score:80,exempt:false}}},
 finals:{u1:{released:false,adjusted:null,snapshot:null},u2:{released:false,adjusted:null,snapshot:null}},
 enrollments:{u1:{role:'learner',multiplier:1},u2:{role:'learner',multiplier:1},u3:{role:'instructor',multiplier:1}},
 content:[{id:'m1',name:'Start Here',body:'Welcome to the practice course. This module contains sample instructions and a course orientation.',visible:true,start:'',end:''},{id:'m2',name:'Week 1 · Foundations',body:'Practice ticket: a learner cannot find this module. Check course access, then module visibility and dates.',visible:false,start:'',end:''}],
 assignments:[{id:'a1',name:'Project submission',instructions:'Submit your practice project. This is synthetic content; the simulator does not upload files.',visible:true,start:'',due:'',end:'',gradeItem:'project'}],
 quizzes:[{id:'quiz1',name:'Quiz 1',minutes:30,attempts:1,visible:true,special:{},gradeItem:'q1'}],
 scheme:[{name:'A',min:90},{name:'B',min:80},{name:'C',min:70},{name:'D',min:60},{name:'F',min:0}]
};}
function initialState(){return {version:1,selectedCourse:'c1',users:[{id:'u1',first:'Demo',last:'Learner',username:'demo.learner',orgId:'DEMO-001',email:'learner@example.invalid',active:true},{id:'u2',first:'Jordan',last:'Example',username:'jordan.example',orgId:'DEMO-002',email:'jordan@example.invalid',active:true},{id:'u3',first:'Practice',last:'Instructor',username:'practice.instructor',orgId:'DEMO-003',email:'instructor@example.invalid',active:true}],roles:[{id:'learner',name:'Learner',canGrade:true,permissions:{content:true,editContent:false,manageAssignments:false,viewSubmissions:false,editGrades:false}},{id:'instructor',name:'Instructor',canGrade:false,permissions:{content:true,editContent:true,manageAssignments:true,viewSubmissions:true,editGrades:true}}],org:{lessonsEnabled:false,lessonsDefault:false},units:[{id:'org',name:'Practice Organization',code:'PRACTICE',type:'Organization',parent:''},{id:'dept',name:'Learning Technology',code:'LT',type:'Department',parent:'org'},{id:'c1',name:'Faculty Support Practice',code:'PRACTICE-101',type:'Course Offering',parent:'dept'},{id:'c2',name:'Department Training',code:'PRACTICE-202',type:'Course Offering',parent:'dept'}],courses:[sampleCourse('c1','Faculty Support Practice','PRACTICE-101'),sampleCourse('c2','Department Training','PRACTICE-202')],notes:[],completed:[]};}
let state=initialState(),storageAvailable=true;
try{const old=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(old?.version===1&&Array.isArray(old.courses)&&Array.isArray(old.users)&&Array.isArray(old.notes))state=old;}catch(e){storageAvailable=false;}
let view={route:'home',tab:'enter',settingsTab:'calculation',learner:'u1',menu:null,tour:null,step:0,ticket:'',matches:[],module:null};
const course=()=>state.courses.find(c=>c.id===state.selectedCourse)||state.courses[0];
const userName=id=>{const u=state.users.find(u=>u.id===id);return u?u.first+' '+u.last:'Unknown user';};
const roleById=id=>state.roles.find(r=>r.id===id);
const learners=c=>state.users.filter(u=>c.enrollments[u.id]&&roleById(c.enrollments[u.id].role)?.canGrade);
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageAvailable=true;}catch(e){storageAvailable=false;}}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3500);}
function gradeRecord(c,user,item){return c.grades[user]?.[item]||{score:null,exempt:false};}
function finalRecord(c,user){return c.finals[user]||(c.finals[user]={released:!!c.settings.autoRelease,adjusted:null,snapshot:null});}

// Documented numeric subset: points/weighted; full precision until display.
function calculate(c,user){
 const warnings=[];const groupResults=[];
 const active=c.items.filter(i=>!i.excluded&&!gradeRecord(c,user,i.id).exempt).map(i=>({...i,score:gradeRecord(c,user,i.id).score}));
 function summarize(items,cat){
   let regular=items.filter(i=>!i.bonus&&(i.score!==null||c.settings.blanks==='zero'));
   const bonus=items.filter(i=>i.bonus&&i.score!==null);
   const allRegular=items.filter(i=>!i.bonus);
   if(cat?.dropLowest){
     const equal=allRegular.length>cat.dropLowest&&allRegular.every(i=>i.score!==null&&i.max===allRegular[0].max&&(c.settings.mode==='points'||i.weight===allRegular[0].weight));
     if(!equal){warnings.push('Drop-lowest is modeled only with completed, equal-point items (and equal weights in Weighted), leaving at least one item.');return null;}
     const drop=new Set([...regular].sort((a,b)=>a.score/a.max-b.score/b.max).slice(0,cat.dropLowest).map(i=>i.id));
     regular=regular.filter(i=>!drop.has(i.id));
   }
   const val=i=>i.canExceed?(i.score??0):Math.min(i.score??0,i.max);
   if(c.settings.mode==='points'){
     const possible=regular.reduce((s,i)=>s+i.max,0);if(!possible)return null;
     let earned=regular.reduce((s,i)=>s+val(i),0)+bonus.reduce((s,i)=>s+val(i),0);
     if(cat&&!cat.canExceed)earned=Math.min(earned,possible);
     return {earned,possible,ratio:earned/possible,weight:cat?.weight??regular[0]?.weight??0};
   }
   const weight=regular.reduce((s,i)=>s+i.weight,0);if(!weight)return null;
   let ratio=regular.reduce((s,i)=>s+i.weight*val(i)/i.max,0)/weight;
   if(bonus.length){
     const expected=c.items.filter(i=>i.categoryId===cat?.id&&!i.bonus&&!i.excluded);
     if(!cat||cat.dropLowest||regular.length!==expected.length||regular.some(i=>i.score===null)||Math.abs(weight-100)>.00001){warnings.push('Weighted bonus with partial, exempt, dropped, or non-100% regular siblings is outside this lab’s calculation model.');return null;}
     ratio+=bonus.reduce((s,i)=>s+i.weight*val(i)/i.max,0)/100;
   }
   if(cat&&!cat.canExceed)ratio=Math.min(ratio,1);
   return {ratio,weight:cat?.weight??regular[0]?.weight??0};
 }
 for(const cat of c.categories){const group=summarize(active.filter(i=>i.categoryId===cat.id),cat);if(group)groupResults.push({...group,name:cat.name});}
 for(const item of active.filter(i=>!i.categoryId&&!i.bonus)){const group=summarize([item],null);if(group)groupResults.push({...group,name:item.name});}
 let result=null;
 if(c.settings.mode==='points'){
   const possible=groupResults.reduce((s,g)=>s+g.possible,0);
   const bonus=active.filter(i=>!i.categoryId&&i.bonus&&i.score!==null).reduce((s,i)=>s+(i.canExceed?i.score:Math.min(i.score,i.max)),0);
   if(possible)result=100*(groupResults.reduce((s,g)=>s+g.earned,0)+bonus)/possible;
 }else{
   const weight=groupResults.reduce((s,g)=>s+g.weight,0);
   if(weight)result=100*groupResults.reduce((s,g)=>s+g.weight*g.ratio,0)/weight;
   const bonus=active.filter(i=>!i.categoryId&&i.bonus&&i.score!==null);
   if(bonus.length&&result!==null){
     const expected=c.items.filter(i=>!i.bonus&&!i.excluded);
     if(Math.abs(weight-100)>.00001||expected.some(i=>gradeRecord(c,user,i.id).score===null||gradeRecord(c,user,i.id).exempt)||c.categories.some(g=>g.dropLowest))warnings.push('Weighted course bonus is modeled only when regular course weights total 100% and all regular items have scores without exemptions or drops.');
     else result+=bonus.reduce((s,i)=>s+i.weight*(i.canExceed?i.score:Math.min(i.score,i.max))/i.max,0);
   }
 }
 if(warnings.length)return {value:null,warnings:[...new Set(warnings)],groups:groupResults};
 if(result!==null&&!c.settings.finalCanExceed)result=Math.min(result,100);
 return {value:result,warnings:[],groups:groupResults};
}
function recalculate(c){for(const u of learners(c))finalRecord(c,u.id).snapshot=calculate(c,u.id).value;}
function changed(message='Saved in this local practice lab.'){if(course().settings.autoUpdate)recalculate(course());persist();render();toast(message);}
for(const c of state.courses)if(c.settings.autoUpdate)recalculate(c);
function displayedFinal(c,id){return c.settings.autoUpdate?calculate(c,id).value:finalRecord(c,id).snapshot;}
function letter(c,value){if(value===null)return '—';return [...c.scheme].sort((a,b)=>b.min-a.min).find(s=>value>=s.min)?.name||'—';}
function dateStatus(start,end){const now=Date.now();if(start&&now<new Date(start).getTime())return 'Not started';if(end&&now>new Date(end).getTime())return 'Closed';return 'Open';}
function courseAccess(c,u){if(!u?.active)return 'Account inactive';if(!c.enrollments[u.id])return 'Not enrolled';if(!c.active)return 'Course inactive';return dateStatus(c.start,c.end);}
function effectiveMinutes(c,q,user){const factor=q.special[user]??c.enrollments[user]?.multiplier??1;return {factor,minutes:q.minutes*factor,source:q.special[user]!==undefined?'Quiz special access':factor!==1?'Course accommodation':'Base time'};}
const navButton=(label,route,extra='')=>`<button class="navitem ${view.route===route?'active':''}" data-action="navigate" data-route="${route}" ${extra}>${label}</button>`;
const action=(label,a,attrs='',cls='')=>`<button type="button" class="${cls}" data-action="${a}" ${attrs}>${label}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${h(label)}</span><input type="${type}" name="${name}" value="${h(value)}" ${extra}></label>`;
const check=(label,name,value,extra='')=>`<label class="choice"><input type="checkbox" name="${name}"${checked(value)} ${extra}><span>${label}</span></label>`;
const radio=(name,value,current,label,help='')=>`<label class="choice"><input type="radio" name="${name}" value="${value}"${checked(value===current)}><span>${label}${help?`<br><span class="help">${help}</span>`:''}</span></label>`;
function selectField(label,name,options,current,extra=''){return `<label class="field"><span>${h(label)}</span><select name="${name}" ${extra}>${options.map(o=>`<option value="${h(o.value)}"${selected(o.value,current)}>${h(o.label)}</option>`).join('')}</select></label>`;}
function savebar(label='Save'){return `<div class="savebar"><button type="submit" class="primary">${label}</button></div>`;}
function menu(name,label,items){return `<div class="dropdown"><button class="navitem" data-action="menu" data-menu="${name}" aria-expanded="${view.menu===name}">${label} ▾</button>${view.menu===name?`<div class="menu">${items.map(([title,route])=>action(title,'navigate',`data-route="${route}"`)).join('')}</div>`:''}</div>`;}
function tabs(entries,current,actionName='grade-tab'){return `<div class="tabs">${entries.map(([id,label])=>action(label,actionName,`data-tab="${id}" aria-current="${current===id?'page':'false'}"`,current===id?'active':'')).join('')}</div>`;}
function prototypeHeader(){return `<header class="topbar"><div class="brandmark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16"/></svg>Practice Campus</div><label class="sr-only" for="course-select">Practice course</label><select id="course-select" class="course-select" data-action="course">${state.courses.map(c=>`<option value="${h(c.id)}"${selected(c.id,course().id)}>${h(c.name)}</option>`).join('')}</select><div class="top-actions"><span class="badge">OFFLINE SIMULATOR</span>${action('Learner view','navigate','data-route="preview"')}${action('⚙ Admin Tools','navigate','data-route="admin"')}</div></header><nav class="navbar" aria-label="Course tools">${navButton('Course Home','home')}${navButton('Content','content')}${menu('course','Course Tools',[['Classlist','classlist'],['Course settings','course-admin']])}${menu('assessments','Assessments',[['Grades','grades'],['Assignments','assignments'],['Quizzes','quizzes']])}${navButton('Course Admin','course-admin')}${navButton('Resources & AI','resources')}</nav><div class="simstrip"><span><b>Practice data only.</b> Independent training model; features and permissions are simplified.</span><span>${storageAvailable?'● Saved in this browser':'Storage unavailable — export notes before closing'}</span></div>`;}
function home(){const c=course();return `<p class="eyebrow">Your learning technology practice course</p><div class="toolbar">${action('Explore 47 captured screens','navigate','data-route="library"')}${action('Replay recorded tour','navigate','data-route="replay"')}${action('Run calculation checks','navigate','data-route="self-check"')}</div><h1>Learn the tools. Work through a ticket.</h1><p class="muted">Use sample learners and course materials to practice the settings you will explain to faculty. Open a guided tour for red highlights and step-by-step explanations.</p><div class="callout">Start with <b>Set up a weighted gradebook</b>. The settings and scores in this lab are editable. Changes affect only this HTML practice file’s browser storage.</div><div class="grid">${[['Grades','Set up weights, enter scores, compare blank and zero, release finals.','grades'],['Assignments','Practice due dates, availability, visibility, and grade-item links.','assignments'],['Quizzes','Set time limits and compare course accommodations with special access.','quizzes'],['Content','Edit sample modules and troubleshoot learner visibility.','content'],['Classlist','Inspect enrollment roles and course quiz accommodations.','classlist'],['Admin Tools','Practice accounts, enrollments, roles, org units, and content configuration.','admin']].map(([title,desc,route])=>`<button class="tile" data-action="navigate" data-route="${route}"><strong>${title} →</strong><small>${desc}</small></button>`).join('')}</div><h2>Practice course at a glance</h2><div class="grid three"><div class="panel">Sample learners<span class="stat">${learners(c).length}</span></div><div class="panel">Grading system<span class="stat" style="font-size:24px">${c.settings.mode==='weighted'?'Weighted':'Points'}</span></div><div class="panel">Tours walked through<span class="stat">${state.completed.length} / ${WORKFLOWS.length}</span></div></div><p class="small muted">Layout inspired by observed Brightspace course navigation and grade settings. This is not a D2L product, an exact replica, or a certification of real-system behavior.</p>`;}
function prototypeGradePage(){const sub=view.tab;return `<div class="row between"><h1>${sub==='calculation'?'Calculation Options':sub==='display'?'Display Options':'Grades'}</h1>${action('Setup walkthrough','tour','data-id="grade-setup"')}</div>${tabs([['enter','Enter Grades'],['manage','Manage Grades'],['schemes','Schemes'],['calculation','Settings']],sub==='display'?'calculation':sub)}${sub==='enter'?enterGrades():sub==='manage'?manageGrades():sub==='schemes'?schemes():gradeSettings()}`;}
function baseEnterGrades(){const c=course(),ls=learners(c);const warnings=[...new Set(ls.flatMap(u=>calculate(c,u.id).warnings))];return `<div class="row between"><p class="muted small">Blank is ungraded. 0 is a score. Exempt removes an item for that learner.</p><div class="actions">${action('Recalculate','recalculate','data-target="recalculate"')}${action('Transfer calculated → adjusted','transfer')}</div></div>${!c.settings.autoUpdate?'<div class="callout warn">Automatic updates are off. Calculated finals show stored values until you choose Recalculate.</div>':''}${warnings.map(w=>`<div class="callout warn">${h(w)} No calculated final is shown for the affected learner.</div>`).join('')}<form data-form="grades"><div class="table-wrap" data-target="grade-table"><table><thead><tr><th>Learner</th>${c.items.map(i=>`<th>${h(i.name)}<br><small>/ ${i.max}${i.hidden?' · hidden':''}${i.bonus?' · bonus':''}${i.excluded?' · excluded':''}</small></th>`).join('')}<th>Calculated<br>Final Grade</th><th>Adjusted<br>Final Grade (%)</th><th data-target="release-controls">Release final</th></tr></thead><tbody>${ls.map(u=>{const f=finalRecord(c,u.id);return `<tr><td><b>${h(userName(u.id))}</b><br><span class="small muted">${c.personal?.showOrgId!==false?h(u.orgId):''}${c.personal?.showUsername?'<br>'+h(u.username):''}</span></td>${c.items.map(i=>{const g=gradeRecord(c,u.id,i.id);return `<td><input class="grade-cell" type="number" step="any" min="0" ${i.canExceed?'':`max="${i.max}"`} name="score:${u.id}:${i.id}" value="${g.score??''}" aria-label="${h(userName(u.id)+' '+i.name+' score')}"><label class="choice small" style="margin:8px 0 0"><input type="checkbox" name="exempt:${u.id}:${i.id}"${checked(g.exempt)}>Exempt</label></td>`;}).join('')}<td class="total">${displayedFinal(c,u.id)===null?'—':displayedFinal(c,u.id).toFixed(c.settings.managingDecimals??2)+'%'}</td><td><input class="grade-cell" type="number" min="0" step="any" name="adjusted:${u.id}" value="${f.adjusted??''}" aria-label="${h(userName(u.id))} adjusted final"></td><td><label class="choice small"><input type="checkbox" name="released:${u.id}"${checked(f.released)}>Released</label></td></tr>`;}).join('')}</tbody></table></div>${ls.length?'':'<div class="blank">No enrolled role is currently marked Can be graded in Grades. Add an enrollment or inspect Roles and Permissions.</div>'}${savebar('Save grades')}<p class="help">Final selected for release: <b>${c.settings.finalType==='calculated'?'Calculated':'Adjusted'}</b>. ${c.settings.blanks==='drop'?'Ungraded items are excluded.':'Ungraded items count as zero.'} ${action('Open learner view','navigate','data-route="preview"','link-button')}</p></form>`;}
function prototypeManageGrades(){const c=course();return `<div class="toolbar">${action('New Grade Item','item','data-id="new"','primary')}${action('New Category','category','data-id="new"')}</div><div class="table-wrap" data-target="manage-categories"><table><thead><tr><th>Category</th><th>Course weight</th><th>Drop lowest</th><th>Options</th></tr></thead><tbody>${c.categories.map(g=>`<tr><td>${h(g.name)}</td><td>${g.weight}%</td><td>${g.dropLowest}</td><td>${action('Edit','category',`data-id="${h(g.id)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="table-wrap" data-target="manage-items"><table><thead><tr><th>Grade item</th><th>Category</th><th>Max points</th><th>Weight</th><th>Flags</th><th></th></tr></thead><tbody>${c.items.map(i=>`<tr><td><b>${h(i.name)}</b></td><td>${h(c.categories.find(g=>g.id===i.categoryId)?.name||'— Course level')}</td><td>${i.max}</td><td>${i.weight}% ${i.categoryId?'<small>of category</small>':''}</td><td>${[i.hidden?'Hidden':'',i.bonus?'Bonus':'',i.excluded?'Excluded':'',i.canExceed?'Can exceed':''].filter(Boolean).map(x=>`<span class="tag">${x}</span>`).join(' ')||'—'}</td><td>${action('Edit','item',`data-id="${h(i.id)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="callout">In Weighted, regular items inside a category normally total 100%. Course-level categories and uncategorized items normally total 100%. In Points, weights are stored but are not used.</div>${weightSummary(c)}<details class="accordion"><summary>Calculation boundaries in this lab</summary><div><p>Numeric items, points/weighted systems, exclusions, exemptions, hidden items, and final release are supported. Full precision is retained until display.</p><p>Drop-lowest requires completed equal-point items and, for Weighted, equal item weights. Weighted bonus is supported only with complete regular scores and 100% regular weights, without dropped or exempt regular items. Other combinations show a model limitation instead of an invented final.</p><p>Formula grades, text/selectbox/pass-fail items, automatic overdue zeros, activity grading sync, and every Brightspace rounding or bonus edge case are not reproduced.</p></div></details>`;}
function weightSummary(c){const total=c.categories.reduce((s,g)=>s+g.weight,0)+c.items.filter(i=>!i.categoryId&&!i.bonus&&!i.excluded).reduce((s,i)=>s+i.weight,0);return `<p class="help">Configured regular course weight: <b>${total}%</b>.${total!==100?' Active weights are normalized for the supported sample calculations; check your intended design.':''}</p>`;}
function prototypeGradeSettings(){const c=course(),s=c.settings;return `${tabs([['calculation','Calculation Options'],['display','Display Options']],view.tab,'grade-tab')}${view.tab==='display'?`<form data-form="display"><h2>Org Unit Display Options · simplified</h2>${check('Show points in learner view','showPoints',s.showPoints)}${check('Show percentages in learner view','showPercent',s.showPercent)}${field('Decimal places in learner view','decimals',s.decimals,'number','min="0" max="4" required')}${savebar()}<p class="help">This lab models two learner-display switches and decimal places. Personal display options, symbols, colors, and all institutional grade displays are not reproduced.</p></form>`:`<form data-form="settings"><section class="section" data-target="grading-system"><h2>Grading System</h2>${radio('mode','weighted',s.mode,'Weighted','Each item or category contributes a percentage of the final grade.')}${radio('mode','points',s.mode,'Points','Earned points divided by possible points; item weights are ignored.')}<label class="choice muted"><input type="radio" disabled><span>Formula <span class="tag">Reference only</span><br><span class="help">Custom formula evaluation is outside this simulator.</span></span></label></section><section class="section" data-target="final-type"><h2>Final Grade Released</h2>${radio('finalType','calculated',s.finalType,'Calculated Final Grade')}${radio('finalType','adjusted',s.finalType,'Adjusted Final Grade')}${check('Automatically release final grade','autoRelease',s.autoRelease)}<p class="help">In this lab, saving automatic release ON releases the selected final for all currently enrolled sample learners. Turning it OFF does not retract existing releases.</p></section><section class="section" data-target="blank-policy"><h2>Grade Calculations</h2>${radio('blanks','drop',s.blanks,'Exclude ungraded items')}${radio('blanks','zero',s.blanks,'Treat ungraded items as 0')}<h3 style="margin-top:26px">Automatic Zero for Missing Submissions</h3><label class="choice muted"><input type="checkbox" disabled><span>Automatically apply a grade of zero to missing submissions once overdue <span class="tag">Reference only</span></span></label><p class="help">Real Brightspace can apply overdue zeros for supported activities when enabled. This file has no background activity processor; practice with explicit zero scores.</p></section><section class="section"><h2>Auto Update</h2>${check('Automatically keep final grades updated','autoUpdate',s.autoUpdate)}${check('Allow calculated final grade to exceed 100% · lab control','finalCanExceed',s.finalCanExceed)}<p class="help">The final Can Exceed option is exposed here for convenient practice; its placement in real Brightspace may differ.</p></section>${savebar()}</form>`}`;}
function prototypeSchemes(){const c=course();return `<h2>Example percentage scheme</h2><p class="help">These are invented practice thresholds, not your institution’s grading policy. They change the symbol in the learner view, not the underlying calculation.</p><form data-form="scheme"><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Minimum percentage</th></tr></thead><tbody>${c.scheme.map((s,i)=>`<tr><td><input name="name:${i}" value="${h(s.name)}" required aria-label="Scheme symbol ${i+1}"></td><td><input type="number" name="min:${i}" value="${s.min}" min="0" max="100" step="any" required aria-label="Minimum for ${h(s.name)}"></td></tr>`).join('')}</tbody></table></div>${savebar('Save scheme')}</form>`;}
function contentPage(){const c=course(),lessons=state.org.lessonsEnabled&&(c.lessonsOverride??state.org.lessonsDefault);return `<div class="row between"><h1>Content</h1>${action('New Module','module','data-id="new"','primary')}</div><div class="row between" data-target="content-experience"><p class="muted">${lessons?'New Content Experience · simplified lessons layout':'Classic Content · simplified module layout'}</p><span class="tag">${lessons?'New':'Classic'}</span></div><div class="${lessons?'grid':'stack'}" data-target="content-list">${c.content.map(m=>`<article class="list-card"><div class="row between"><h3>${h(m.name)}</h3><span class="tag ${m.visible?'on':'off'}">${m.visible?'Visible':'Hidden'}</span></div><div class="content-body">${h(m.body)}</div><div class="summary-line"><span>Start: ${h(m.start||'No restriction')}</span><span>End: ${h(m.end||'No restriction')}</span></div><div class="toolbar">${action('Edit module','module',`data-id="${h(m.id)}"`)}</div></article>`).join('')}</div><p class="help">Visibility and dates are functional. Nested topics, release conditions, completion rules, SCORM, and file rendering are not modeled.</p>`;}
function assignmentsPage(){const c=course();return `<div class="row between"><h1>Assignments</h1>${action('New Assignment','assignment','data-id="new"','primary')}</div><div data-target="assignment-list">${c.assignments.map(a=>`<article class="list-card"><div class="row between"><h3>${h(a.name)}</h3><span class="tag ${a.visible?'on':'off'}">${a.visible?'Visible':'Hidden'}</span></div><p>${h(a.instructions)}</p><div class="summary-line"><span>Due: ${h(a.due||'Not set')}</span><span>End: ${h(a.end||'No cutoff')}</span><span>Grade item: ${h(c.items.find(i=>i.id===a.gradeItem)?.name||'None')}</span></div><div class="toolbar">${action('Edit assignment','assignment',`data-id="${h(a.id)}"`)}${action('Manage Special Access','assignment-special',`data-id="${h(a.id)}"`)}</div></article>`).join('')}</div><div class="callout">A due date marks a deadline. An end date controls the submission cutoff modeled here. Visibility and availability are separate settings.</div><p class="help">Grade-item links are stored for practice. Submissions, rubric evaluation, Turnitin, feedback publishing, and automatic grade synchronization are not implemented.</p>`;}
function quizzesPage(){const c=course();return `<div class="row between"><h1>Manage Quizzes</h1>${action('New Quiz','quiz','data-id="new"','primary')}</div><div data-target="quiz-list">${c.quizzes.map(q=>`<article class="list-card"><div class="row between"><h3>${h(q.name)}</h3><span class="tag ${q.visible?'on':'off'}">${q.visible?'Visible':'Hidden'}</span></div><div class="summary-line"><span>${q.minutes} minute time limit</span><span>${q.attempts} allowed attempt${q.attempts===1?'':'s'}</span><span>${Object.keys(q.special).length} special-access override(s)</span></div><div class="toolbar">${action('Edit quiz','quiz',`data-id="${h(q.id)}"`)}${action('Manage Special Access','special',`data-id="${h(q.id)}"`)}</div></article>`).join('')}</div><div class="callout">Special Access changes one quiz. Classlist accommodations apply across quizzes in this course. The lab calculates effective time using a quiz override first, then the course accommodation.</div><p class="help">Questions, quiz-taking, automatic evaluation, timing enforcement, attempt-level exceptions, and quiz availability dates are not modeled. Real Quiz Preview does not apply learner-specific special access or accommodations.</p>`;}
function classlist(){const c=course();return `<div class="row between"><h1>Classlist</h1>${action('Manage enrollments','navigate','data-route="admin-users"')}</div><div class="table-wrap" data-target="classlist-table"><table><thead><tr><th>Name</th><th>Role in this course</th><th>Quiz timing accommodation</th><th>Account</th><th></th></tr></thead><tbody>${state.users.filter(u=>c.enrollments[u.id]).map(u=>`<tr><td>${h(userName(u.id))}</td><td>${h(roleById(c.enrollments[u.id].role)?.name)}</td><td>${c.enrollments[u.id].accommodationKind==='extra'?'+ '+(c.enrollments[u.id].extraMinutes||0)+' minutes':'× '+c.enrollments[u.id].multiplier}</td><td><span class="tag ${u.active?'on':'off'}">${u.active?'Active':'Inactive'}</span></td><td>${roleById(c.enrollments[u.id].role)?.canGrade?action('Edit Accommodations','accommodation-v2',`data-id="${h(u.id)}"`):'—'}</td></tr>`).join('')}</tbody></table></div><p class="help">Enrollment role and organization account status are separate. The lab lists all enrolled roles; real Classlist display depends on role settings.</p>`;}
function courseAdmin(){const c=course();return `<h1>Course Admin</h1><div class="grid three">${[['Grades','grades'],['Assignments','assignments'],['Quizzes','quizzes'],['Content','content'],['Classlist','classlist'],['Organization tools','admin']].map(([title,route])=>`<button class="tile" data-action="navigate" data-route="${route}"><strong>${title}</strong></button>`).join('')}</div><form data-form="course"><h2>Course Offering Information · practice subset</h2>${field('Course Offering Name','name',c.name,'text','required maxlength="90"')}${field('Course Offering Code','code',c.code,'text','required maxlength="40"')}<div data-target="course-availability">${check('Course is active','active',c.active)}${field('Start date','start',c.start,'datetime-local')}${field('End date','end',c.end,'datetime-local')}</div>${savebar('Save course information')}</form><p class="help">Course dates use your computer’s local time. Staff access exceptions, sections, completion tracking, course copying, and full course administration are not modeled.</p>`;}
function learnerPreview(){const c=course(),ls=learners(c);if(!ls.some(u=>u.id===view.learner))view.learner=ls[0]?.id;const u=ls.find(u=>u.id===view.learner);if(!u)return '<h1>Simulated learner view</h1><div class="blank">Enroll a user with a gradeable role to preview a learner.</div>';const access=courseAccess(c,u),f=finalRecord(c,u.id),final=c.settings.finalType==='calculated'?displayedFinal(c,u.id):f.adjusted;return `<div class="row between"><h1>Simulated learner view</h1><label>View as <select data-action="learner">${ls.map(x=>`<option value="${h(x.id)}"${selected(x.id,u.id)}>${h(userName(x.id))}</option>`).join('')}</select></label></div><div class="callout">A local teaching view of the settings this lab supports. This is not Brightspace’s View as Learner or Quiz Preview.</div><div class="panel"><h3>Course access: ${h(access)}</h3><p class="small muted">Checks organization account status, enrollment, course active flag, and course dates. Uses this computer’s current date and time.</p></div>${access!=='Open'?'<div class="blank" style="margin-top:20px">Course tools are unavailable for this sample learner until access is open.</div>':`<section data-target="learner-grades"><h2>Grades</h2><div class="table-wrap"><table><thead><tr><th>Grade item</th><th>Result</th></tr></thead><tbody>${c.items.filter(i=>!i.hidden).map(i=>{const g=gradeRecord(c,u.id,i.id),v=g.score===null?null:100*g.score/i.max;return `<tr><td>${h(i.name)}</td><td>${g.exempt?'Exempt':g.score===null?'Not graded':`${learnerGradeValue(c,i,g.score)}`}</td></tr>`;}).join('')}<tr><td><b>Final grade</b></td><td class="total">${f.released?(final===null?'No final value':`${final.toFixed(c.settings.decimals)}%${c.settings.showScheme&&c.settings.schemeName==='Practice scheme'?' · '+h(letter(c,final)):''}`):'Not released'}</td></tr></tbody></table></div>${c.settings.showCalculation?learnerCalculation(c,u.id):''}</section><section data-target="learner-content"><h2>Content</h2>${c.content.filter(m=>m.visible&&dateStatus(m.start,m.end)==='Open').map(m=>`<div class="list-card"><h3>${h(m.name)}</h3><p>${h(m.body)}</p></div>`).join('')||'<div class="blank">No visible modules are currently available.</div>'}</section><section data-target="learner-assignments"><h2>Assignments</h2>${c.assignments.filter(a=>a.visible).map(a=>{const ad=assignmentDates(a,u.id);let status=dateStatus(ad.start,ad.end);if(status==='Open'&&ad.due&&Date.now()>new Date(ad.due).getTime())status='Overdue · submission window open';return `<div class="list-card"><div class="row between"><h3>${h(a.name)}</h3><span class="tag">${h(status)}</span></div><p class="small">Due: ${h(ad.due||'Not set')} · End: ${h(ad.end||'No cutoff')}</p></div>`;}).join('')||'<div class="blank">No visible assignments.</div>'}</section><section data-target="learner-quizzes"><h2>Quizzes</h2>${c.quizzes.filter(q=>q.visible).map(q=>{const t=effectiveMinutes(c,q,u.id);return `<div class="list-card"><h3>${h(q.name)}</h3><p><b>${t.minutes} minutes</b> effective time · ${h(t.source)}</p><p class="help">${t.source==='Quiz special access'?t.minutes+' minutes explicitly set for this quiz; overrides the course accommodation':q.minutes+' base minutes'+(t.extra?' + '+t.extra+' extra minutes':' × '+t.factor)}. Allowed attempts: ${q.attempts}. No quiz attempt or timer is running.</p></div>`;}).join('')||'<div class="blank">No visible quizzes.</div>'}</section>`}`;}
const PERMISSIONS=[['content','See course content'],['editContent','Edit course content'],['manageAssignments','See and manage assignment folders'],['viewSubmissions','View submitted files'],['editGrades','Edit grades']];
function adminNav(){return tabs([['admin','Overview'],['admin-users','Users'],['admin-roles','Roles and Permissions'],['admin-units','Org Unit Editor'],['admin-config','Config Variables']],view.route,'admin-tab');}
function adminPage(){return `<p class="eyebrow">Organization administration · practice subset</p><h1>${({'admin':'Admin Tools','admin-users':'Users','admin-roles':'Roles and Permissions','admin-units':'Org Unit Editor','admin-config':'Config Variable Browser'})[view.route]}</h1>${adminNav()}${view.route==='admin-users'?adminUsers():view.route==='admin-roles'?adminRoles():view.route==='admin-units'?adminUnits():view.route==='admin-config'?adminConfig():adminHome()}`;}
function adminHome(){return `<div class="callout warn">These organization-wide screens were not captured in your MSU pack. This is a small, functioning training model of selected admin concepts. It does not reproduce all Brightspace administrative settings, role interactions, security, or backend behavior.</div><div class="grid">${[['Users & Enrollments','Create synthetic accounts and assign a different role in each course.','admin-users'],['Roles and Permissions','Copy a practice role and inspect its effect in a simulated access checker.','admin-roles'],['Org Unit Editor','Build a simplified, single-parent organization hierarchy.','admin-units'],['Config Variable Browser','Practice organization capability, an inherited default, and a course override.','admin-config']].map(([t,d,r])=>`<button class="tile" data-action="navigate" data-route="${r}"><strong>${t} →</strong><small>${d}</small></button>`).join('')}</div><h2>Systems that need a real test environment</h2>${[['Identity & authentication','Single sign-on, SAML/LDAP, passwords, session revocation, and real authorization.'],['Student systems & integrations','SIS/IPSIS roster synchronization, LTI launches and grade return, Turnitin, publishers, and video services.'],['Operations & reporting','Email delivery, live APIs, production analytics, bulk jobs, course import/export compatibility, archive, purge, and restore.']].map(([t,d])=>`<details class="accordion"><summary>${t} · reference only</summary><div><p>${d}</p><p class="help">Practice the actual workflow in an institution-approved test environment with appropriate access. No service call or background task is performed by this file.</p></div></details>`).join('')}`;}
function adminUsers(){return `<div class="toolbar">${action('New User','user','data-id="new" data-target="new-user"','primary')}</div><div class="table-wrap" data-target="users-table"><table><thead><tr><th>Name</th><th>Username / Org Defined ID</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${h(userName(u.id))}<br><small>${h(u.email)}</small></td><td>${h(u.username)}<br><small>${h(u.orgId)}</small></td><td><span class="tag ${u.active?'on':'off'}">${u.active?'Active':'Inactive'}</span></td><td><div class="actions">${action('Edit','user',`data-id="${h(u.id)}"`)}${action('Enrollments','enroll',`data-id="${h(u.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div><p class="help">New accounts are not enrolled automatically. This lab omits organization-role assignment and cascading roles. Use invented names and addresses; no password or email service exists here.</p>`;}
function adminRoles(){return `<div class="toolbar">${action('Create / Copy Role','copy-role','','primary')}${action('Check a user’s access','access-check')}</div><div data-target="roles-list">${state.roles.map(r=>`<div class="list-card"><div class="row between"><h3>${h(r.name)}</h3>${action('Edit Permissions','permissions',`data-id="${h(r.id)}"`)}</div><p class="small muted">Can be graded: ${r.canGrade?'Yes':'No'} · Course permissions enabled: ${Object.values(r.permissions).filter(Boolean).length} / ${PERMISSIONS.length}</p></div>`).join('')}</div><div class="callout warn">Editing a role definition changes the permissions used by that role across all sample courses. Assigning that role to one course enrollment controls where the individual receives it.</div><p class="help">Only the five displayed course permissions are modeled. Use Check a user’s access to see their effect. Your operator controls stay available so you can practice and repair settings. Real roles also have settings, interactions, org-unit scope, dependencies, and inheritance.</p>`;}
function adminUnits(){return `<div class="toolbar">${action('New Org Unit','unit','data-id="new"','primary')}</div><div class="callout">Simplified single-parent tree. Real Brightspace course offerings can relate to templates, semesters, and other units; this is not the full organization model.</div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Code</th><th>Type</th><th>Parent</th><th></th></tr></thead><tbody>${state.units.map(u=>`<tr><td>${h(u.name)}</td><td>${h(u.code)}</td><td>${h(u.type)}</td><td>${h(state.units.find(p=>p.id===u.parent)?.name||'—')}</td><td>${u.id==='org'?'Root':action('Edit','unit',`data-id="${h(u.id)}"`)}</td></tr>`).join('')}</tbody></table></div><p class="help">Creating a Course Offering here creates an empty practice course with default settings. Other unit types are hierarchy records only.</p>`;}
function adminConfig(){const c=course();return `<form data-form="config"><div class="section" data-target="org-content-config"><h2>Organization capability</h2><p><code>d2l.Tools.Content.IsLessonsEnabled</code></p>${check('Allow New Content Experience in the organization','lessonsEnabled',state.org.lessonsEnabled)}<p class="help">This permits the experience. It does not by itself switch courses.</p></div><div class="section"><h2>Default course choice · lab model</h2>${check('Use New Content Experience for courses without an override','lessonsDefault',state.org.lessonsDefault)}<p class="help">The lab demonstrates inheritance explicitly. Real variable defaults, overrides, and permissions must be verified for your organization.</p></div><div class="section" data-target="course-content-config"><h2>Course override: ${h(c.name)}</h2><p><code>d2l.Tools.Content.UseLessonsExperience</code></p>${selectField('Value for this course','lessonsOverride',[{value:'inherit',label:'No override — inherit default'},{value:'on',label:'ON — New Content Experience'},{value:'off',label:'OFF — Classic Content'}],c.lessonsOverride===null?'inherit':c.lessonsOverride?'on':'off')}<p class="help">Effective practice experience: <b>${state.org.lessonsEnabled&&(c.lessonsOverride??state.org.lessonsDefault)?'New':'Classic'}</b>. Removing an override restores inheritance.</p></div>${savebar('Save configuration')}</form><p class="help">This is a two-variable teaching model, not the complete Config Variable Browser. No institution configuration is affected.</p>`;}
function resources(){return `<h1>Resources & AI tutor</h1><div class="toolbar">${action('Captured screen library','navigate','data-route="library"')}${action('Replay Claude’s tours','navigate','data-route="replay"')}${action('Calculation self-check','navigate','data-route="self-check"')}</div><p class="muted">Use this file as a practice surface and export the notebook as a compact reference for another AI. The lab itself has no AI model, API key, or background learning service.</p><div class="grid"><div class="panel"><h3>Portable learning notebook</h3><p class="small">Contains your notes, tours walked through, tour steps, course settings, and synthetic practice data. It does not label practice as real-system verification.</p>${action('Export notebook (.json)','export','','primary')}</div><div class="panel"><h3>Start another practice session</h3><p class="small">Edits are saved in this browser when local storage is available. Keep the same file and browser. Export notes before clearing browser data or moving computers.</p>${action('Reset practice data','reset','','danger')}</div></div><h2>Instructions for your browser AI</h2><div class="panel"><p class="notes" id="ai-prompt">You are my Brightspace support tutor. This page is an independent offline simulator. Start by reading its Resources & AI page and embedded workflow-library JSON. If WebMCP tools are available, use them; otherwise use visible browser controls. Ask what skill or sanitized ticket I want to practice, find the closest built-in tour, and start it. Explain one step at a time: what to click, why the setting matters, what result to expect, and how to verify it. Match the substantive level of the supplied Claude tour cards: explain the setting’s purpose, important distinctions, concrete ticket implications, and verification. Skip obvious interface mechanics. Let me control the pace and make changes when useful. Use the red-box tours to guide me. Never present simulated behavior or my practice notes as verified institution behavior. For features outside the modeled subset, consult current official D2L documentation and record what still needs checking in the real sandbox. At the end, help me write a short learning note and export the notebook. Reuse relevant exported notes in later sessions, checking their date and scope.</p>${action('Copy tutor instructions','copy-prompt')}</div><h2>My learning notes</h2><form data-form="note"><label class="field"><span>What did you learn, and what still needs checking?</span><textarea name="note" required maxlength="4000" placeholder="Example: In the weighted sample, excluding a blank quiz changed 70% to 86%. Need to confirm our department’s blank-grade policy in the real sandbox."></textarea></label>${savebar('Save learning note')}</form>${state.notes.slice().reverse().map(n=>`<div class="list-card"><p class="small muted">${h(new Date(n.date).toLocaleString())} · ${h(n.scope)}</p><p class="notes">${h(n.text)}</p></div>`).join('')||'<p class="muted">Your notes will appear here. Saving a note does not train an AI model.</p>'}<h2>What this file covers</h2><div class="panel"><p><b>Working practice features:</b> course selection; numeric points/weighted grade calculations in the documented subset; items and categories; exemptions; blank policy; final release; display options; example schemes; editable content and assignment availability; quiz timing overrides; users and enrollments; selected role permissions and access checks; a simplified org hierarchy; content-experience configuration; guided tours; persistent notes and export.</p><p><b>Not reproduced:</b> full Brightspace administration, backend authorization, SSO, integrations, real enrollments, submissions or quiz delivery, all grade types and calculation edge cases, the full release-condition engine, file storage, course-copy compatibility, rubrics, discussions, groups, analytics, automation, or background jobs.</p><p class="small muted">A local HTML file cannot read or alter your institution’s D2L page on its own. A separate approved browser tool may navigate either surface. Practice here does not confer access or replace a real approved test course.</p></div><h2>Official reference library</h2><p class="small muted">Capture pack and source review: September 22, 2026. The screen library contains all 47 supplied screen records; the editable forms model selected behaviors. Your institution’s navigation, permissions, policies, and enabled features may differ.</p><div class="source-list">${source('D2L: Set up your grade book','https://community.d2l.com/brightspace/kb/articles/3539-set-up-your-grade-book')}${source('D2L: Grading systems and types','https://community.d2l.com/brightspace/kb/articles/3521-grading-systems-types')}${source('D2L: How grade exemptions affect calculations','https://community.d2l.com/brightspace/kb/articles/3536-how-grade-exemptions-affect-calculations')}${source('D2L: Drop the lowest grade','https://community.d2l.com/brightspace/kb/articles/6122-drop-the-lowest-grade')}${source('MSU: Gradebook extra credit','https://help.d2l.msu.edu/msu-docs/d2l-grades-at-msu/d2l-gradebook-extra-credit')}${source('D2L: Create an individual user','https://community.d2l.com/brightspace/kb/articles/4209-create-an-individual-user')}${source('D2L: Enroll users','https://community.d2l.com/brightspace/kb/articles/4860-enroll-users')}${source('D2L: Managing roles and permissions','https://community.d2l.com/brightspace/kb/articles/4452-managing-roles-and-permissions')}${source('D2L: Create and delete org units','https://community.d2l.com/brightspace/kb/articles/4203-create-and-delete-org-units')}${source('D2L: Set up Lessons','https://community.d2l.com/brightspace/kb/articles/4802-set-up-lessons')}</div>`;}
function coach(){if(view.tour){const t=WORKFLOWS.find(t=>t.id===view.tour),s=t.steps[view.step];return `<aside class="coach" aria-label="Guided tutorial"><div class="row between"><span class="eyebrow" style="margin:0">Guided walkthrough</span>${action('Close','close-tour','','quiet small')}</div><h2 style="margin-top:18px">${h(t.title)}</h2><div class="tour-progress"><i style="width:${100*(view.step+1)/t.steps.length}%"></i></div><span class="step-no">STEP ${view.step+1} OF ${t.steps.length}</span><h3 style="margin-top:12px">${h(s.title)}</h3><p>${h(s.body)}</p><p class="small muted">Use the red outline to locate the control. Save your edits before advancing; Next does not perform the change.</p><div class="coach-controls">${action('Back','tour-back',''+(view.step===0?'disabled':''))}${action(view.step===t.steps.length-1?'Finish tour':'Next →','tour-next','','primary')}</div><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><label class="field"><span>Quick learning note</span><textarea id="quick-note" placeholder="What changed? What needs real-world verification?" maxlength="4000"></textarea></label>${action('Save note','quick-note')}</aside>`;}
const matches=view.matches.length?WORKFLOWS.filter(t=>view.matches.includes(t.id)):WORKFLOWS;return `<aside class="coach" aria-label="Practice coach"><p class="eyebrow">Your practice coach</p><h2>What do you want to learn?</h2><p>Choose a guided tour or find one from a short, sanitized ticket description.</p><form data-form="ticket"><label class="sr-only" for="ticket-input">Practice ticket or topic</label><textarea id="ticket-input" name="ticket" placeholder="Example: final grade is not visible" maxlength="1500">${h(view.ticket)}</textarea><button class="primary" type="submit" style="width:100%;margin-top:9px">Find a practice tour</button></form><p class="small muted">Local keyword matching, not AI diagnosis. Use a browser AI for conversation.</p>${view.ticket?`<p class="small">${view.matches.length?'Suggested tours':'No close match. Browse the tours below.'} ${action('Clear','clear-ticket','','link-button')}</p>`:''}${matches.map(t=>`<button class="tour-button" data-action="tour" data-id="${h(t.id)}"><span>${h(t.title)}${state.completed.includes(t.id)?' ✓':''}</span><small>${t.steps.length} steps</small></button>`).join('')}<p class="small muted">✓ means you walked through the tour, not that the workflow was verified in real D2L.</p></aside>`;}
const ROUTES=['home','grades','content','assignments','quizzes','classlist','course-admin','preview','admin','admin-users','admin-roles','admin-units','admin-config','resources'];
function render(){const page=view.route==='home'?home():view.route==='grades'?gradePage():view.route==='content'?contentPage():view.route==='assignments'?assignmentsPage():view.route==='quizzes'?quizzesPage():view.route==='classlist'?classlist():view.route==='course-admin'?courseAdmin():view.route==='course-offering'?courseOfferingPage():view.route==='preview'?learnerPreview():view.route==='library'?libraryPage():view.route==='replay'?replayPage():view.route==='self-check'?selfCheckPage():view.route.startsWith('admin')?adminPage():resources();document.getElementById('app').innerHTML=header()+`<div class="workspace ${view.tour?'touring':''} ${['library','replay','self-check','course-admin'].includes(view.route)?'wide-workspace':''}"><main class="main" id="main">${page}</main></div>${trainingLauncher()}`;requestAnimationFrame(()=>{highlight(false);if(view.route==='replay')replayHighlight();});}
function navigate(route,tab){if(!ROUTES.includes(route))throw Error('Unknown training tool');if(typeof stopReplay==='function')stopReplay();clearTimeout(walkthroughTimer);walkthroughPlaying=false;view.tour=null;view.route=route;if(tab)view.tab=tab;view.menu=null;render();window.scrollTo(0,0);}
function startTour(id){const t=WORKFLOWS.find(t=>t.id===id);if(!t)throw Error('Unknown tour');if(['grade-setup','blank-zero','release-final','content-hidden','assignment-dates','quiz-special','course-accommodation'].includes(id)&&!course().items.length){const example=state.courses.find(c=>c.items.length);if(example)state.selectedCourse=example.id;}view.tour=id;view.step=0;showStep();}
function showStep(){const s=WORKFLOWS.find(t=>t.id===view.tour).steps[view.step];view.route=s.route;view.tab=s.tab||view.tab;view.menu=null;render();requestAnimationFrame(()=>highlight(true));}
function highlight(scroll){document.querySelectorAll('.tour-target').forEach(e=>e.classList.remove('tour-target'));const pop=document.getElementById('tour-popover');pop.hidden=true;if(!view.tour)return;const s=WORKFLOWS.find(t=>t.id===view.tour).steps[view.step];if(s.route!==view.route||(s.tab&&s.tab!==view.tab))return;const el=document.querySelector(`[data-target="${s.target}"]`);if(!el)return;el.classList.add('tour-target');if(scroll)el.scrollIntoView({behavior:'instant',block:'nearest'});const r=el.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;pop.innerHTML=`<b>${h(s.title)}</b>${h(s.body)}`;pop.hidden=false;const w=Math.min(340,innerWidth-40);pop.style.width=w+'px';pop.style.left=Math.max(16,Math.min(r.left+12,innerWidth-w-16))+'px';const height=pop.offsetHeight;let top=r.bottom+12;if(top+height>innerHeight-15)top=r.top-height-12;if(top<15){pop.hidden=true;return;}pop.style.top=top+'px';}
function openDialog(title,body){const d=document.getElementById('dialog');d.innerHTML=`<div class="row between"><h2 id="dialog-title">${h(title)}</h2>${action('✕','close-dialog','aria-label="Close dialog"','quiet')}</div>${body}`;document.getElementById('tour-popover').hidden=true;d.showModal();const tour=activeWalkthrough();if(tour){const tip=document.createElement('details');tip.className='modal-step-help';tip.open=true;tip.innerHTML='<summary>Walkthrough: '+h(tour.title)+'</summary><p class="notes">'+h(tour.body)+'</p>';d.querySelector('form')?.before(tip);highlight(false);}}
function closeDialog(){document.getElementById('dialog').close();highlight(false);}
function modalForm(kind,id,body,label='Save'){return `<form data-form="${kind}" data-id="${h(id)}">${body}<div class="savebar"><button class="primary" type="submit">${label}</button>${action('Cancel','close-dialog')}</div></form>`;}
function itemDialog(id){const c=course(),i=c.items.find(i=>i.id===id)||{name:'',max:10,weight:0,categoryId:null,bonus:false,canExceed:false,excluded:false,hidden:false};openDialog(id==='new'?'New Grade Item':'Edit Grade Item',modalForm('item',id,field('Name','name',i.name,'text','required maxlength="80"')+field('Maximum points','max',i.max,'number','min="0.01" step="any" required')+field('Weight (%)','weight',i.weight,'number','min="0" step="any" required')+selectField('Category','categoryId',[{value:'',label:'None — course level'},...c.categories.map(g=>({value:g.id,label:g.name}))],i.categoryId||'')+check('Bonus item','bonus',i.bonus)+check('Can Exceed maximum points','canExceed',i.canExceed)+(c.settings.mode==='points'?check('Exclude from Final Grade Calculation','excluded',i.excluded):'<p class="help">To exclude a weighted item’s contribution, set its Weight to 0.</p>')+check('Hidden from learners','hidden',i.hidden)+'<p class="help">A hidden item still contributes unless excluded. This is a condensed practice form. In the captured real editor, switching Properties → Restrictions saved the item immediately; Cancel there did not undo creation.</p>'));}
function categoryDialog(id){const c=course(),g=c.categories.find(g=>g.id===id)||{name:'',weight:0,canExceed:false,dropLowest:0};openDialog(id==='new'?'New Category':'Edit Category',modalForm('category',id,field('Name','name',g.name,'text','required maxlength="80"')+field('Course weight (%)','weight',g.weight,'number','min="0" step="any" required')+field('Number of lowest non-bonus items to drop','dropLowest',g.dropLowest,'number','min="0" max="20" step="1" required')+check('Category Can Exceed','canExceed',g.canExceed)+'<p class="help">The New Category form was not captured; this form is a practice model. Drop-lowest is calculated only when all remaining regular items are graded, equal in maximum points, and (for Weighted) equal in weight. At least one must remain.</p>'));}
function moduleDialog(id){const m=course().content.find(m=>m.id===id)||{name:'',body:'',visible:false,start:'',end:''};openDialog(id==='new'?'New Module':'Edit Module',modalForm('module',id,field('Module title','name',m.name,'text','required maxlength="100"')+`<label class="field"><span>Module text</span><textarea name="body" maxlength="10000">${h(m.body)}</textarea></label>`+check('Visible to learners','visible',m.visible)+field('Start date','start',m.start,'datetime-local')+field('End date','end',m.end,'datetime-local')));}
function prototypeAssignmentDialog(id){const c=course(),a=c.assignments.find(a=>a.id===id)||{name:'',instructions:'',visible:false,start:'',due:'',end:'',gradeItem:''};openDialog(id==='new'?'New Assignment':'Edit Assignment',modalForm('assignment',id,field('Name','name',a.name,'text','required maxlength="100"')+`<label class="field"><span>Instructions</span><textarea name="instructions" maxlength="10000">${h(a.instructions)}</textarea></label>`+check('Visible to learners','visible',a.visible)+field('Start date','start',a.start,'datetime-local')+field('Due date','due',a.due,'datetime-local')+field('End date','end',a.end,'datetime-local')+selectField('Grade item — stored link only','gradeItem',[{value:'',label:'None'},...c.items.map(i=>({value:i.id,label:i.name}))],a.gradeItem)+'<p class="help">Due marks a deadline. End closes the modeled submission window. Uploads and grade synchronization are not implemented.</p>'));}
function prototypeQuizDialog(id){const c=course(),q=c.quizzes.find(q=>q.id===id)||{name:'',minutes:30,attempts:1,visible:false,gradeItem:''};openDialog(id==='new'?'New Quiz':'Edit Quiz',modalForm('quiz',id,field('Name','name',q.name,'text','required maxlength="100"')+field('Time limit (minutes)','minutes',q.minutes,'number','min="1" max="1440" step="1" required')+field('Allowed attempts','attempts',q.attempts,'number','min="1" max="99" step="1" required')+check('Visible to learners','visible',q.visible)+selectField('Grade item — stored link only','gradeItem',[{value:'',label:'None'},...c.items.map(i=>({value:i.id,label:i.name}))],q.gradeItem)+'<p class="help">No question editor, attempt delivery, or grading service is modeled.</p>'));}
function prototypeSpecialDialog(id){const q=course().quizzes.find(q=>q.id===id);openDialog('Special Access · '+q.name,modalForm('special',id,`<p class="help">Set a quiz-specific time multiplier, or leave blank to use the course accommodation. This lab does not model other special-access settings.</p>${learners(course()).map(u=>field(userName(u.id)+' · multiplier','factor:'+u.id,q.special[u.id]??'','number','min="0.1" max="10" step="0.1"')).join('')}`));}
function userDialog(id){const u=state.users.find(u=>u.id===id)||{first:'',last:'',username:'',orgId:'',email:'',active:true};openDialog(id==='new'?'New User · synthetic account':'Edit User',modalForm('user',id,field('Legal First Name','first',u.first,'text','required maxlength="60"')+field('Legal Last Name','last',u.last,'text','required maxlength="60"')+field('Username','username',u.username,'text','required maxlength="60"')+field('Org Defined ID','orgId',u.orgId,'text','required maxlength="60"')+field('Email address · use example.invalid','email',u.email,'email','maxlength="120"')+check('Make user active','active',u.active)+'<p class="help">Account creation does not enroll the user. No message is sent. Organization-level roles and cascading enrollments are not modeled.</p>'));}
function enrollmentDialog(id){openDialog('Enrollments · '+userName(id),modalForm('enroll',id,`<p class="help">Choose a role per course. No enrollment removes course access. Role definitions are managed separately.</p>${state.courses.map(c=>selectField(c.name,'role:'+c.id,[{value:'',label:'No enrollment'},...state.roles.map(r=>({value:r.id,label:r.name}))],c.enrollments[id]?.role||'')).join('')}`,'Apply'));}
function permissionDialog(id){const r=roleById(id);openDialog('Edit Permissions · '+r.name,modalForm('permissions',id,`<div class="callout warn">Scope: Course Offering. This edits the role everywhere it is used in the sample courses.</div>${check('Can be graded in Grades · role setting','canGrade',r.canGrade)}<h3>Simulated course permissions</h3>${PERMISSIONS.map(([key,label])=>check(label,key,r.permissions[key])).join('')}<p class="help">View submitted files requires See and manage assignment folders. The access checker applies this dependency. This is a small subset, not an institution-ready role definition.</p>`,'Save and Close'));}
function unitDialog(id){const u=state.units.find(u=>u.id===id)||{name:'',code:'',type:'Department',parent:'org'};openDialog(id==='new'?'Create Org Unit':'Edit Org Unit',modalForm('unit',id,field('Name','name',u.name,'text','required maxlength="90"')+field('Code','code',u.code,'text','required maxlength="40"')+selectField('Type','type',['Department','Semester','Course Template','Course Offering'].map(x=>({value:x,label:x})),u.type,id==='new'?'':'disabled')+selectField('Parent · simplified model','parent',state.units.filter(p=>p.id!==id&&p.type!=='Course Offering').map(p=>({value:p.id,label:p.name})),u.parent)+'<p class="help">The lab permits one parent. A new Course Offering creates an empty practice course; other types create hierarchy records only.</p>',id==='new'?'Create':'Save'));}
function accessCheck(userId=state.users[0]?.id,courseId=course().id){const c=state.courses.find(c=>c.id===courseId),u=state.users.find(u=>u.id===userId),access=courseAccess(c,u),r=roleById(c.enrollments[u.id]?.role),p=r?.permissions||{};openDialog('Simulated access checker',`<form data-form="access-check">${selectField('User','userId',state.users.map(u=>({value:u.id,label:userName(u.id)})),userId)}${selectField('Course','courseId',state.courses.map(c=>({value:c.id,label:c.name})),courseId)}<button type="submit" class="primary">Check access</button></form><div class="callout">Course access: <b>${h(access)}</b> · Role: <b>${h(r?.name||'None')}</b></div><div class="table-wrap"><table><thead><tr><th>Simulated action</th><th>Effective access</th></tr></thead><tbody>${PERMISSIONS.map(([key,label])=>{const allowed=access==='Open'&&p[key]&&(key!=='viewSubmissions'||p.manageAssignments);return `<tr><td>${h(label)}</td><td><span class="tag ${allowed?'on':'off'}">${allowed?'Allowed':'Blocked'}</span></td></tr>`;}).join('')}</tbody></table></div><p class="help">This checker enforces only the displayed practice permission model. Staff date/inactive exceptions and real Brightspace authorization are not reproduced.</p>`);}

function formValue(fd,key){return String(fd.get(key)??'').trim();}
function num(fd,key,min=0,max=Infinity){const raw=formValue(fd,key),v=Number(raw);if(raw===''||!Number.isFinite(v)||v<min||v>max)throw Error('Enter a valid value for '+key+'.');return v;}
function datesValid(start,end){if(start&&end&&new Date(start)>new Date(end))throw Error('The end date must be on or after the start date.');}
function put(list,id,record,prefix){const i=list.findIndex(x=>x.id===id);if(i>=0)list[i]={...list[i],...record};else list.push({id:uid(prefix),...record});}
function saveGrade(c,userId,itemId,score,exempt=false){const i=c.items.find(i=>i.id===itemId);if(!i||!learners(c).some(u=>u.id===userId))throw Error('Unknown enrolled learner or grade item.');if(score!==null&&(!Number.isFinite(score)||score<0||(!i.canExceed&&score>i.max)))throw Error('Score is outside the allowed range.');c.grades[userId]??={};c.grades[userId][itemId]={score,exempt:!!exempt};}
function saveNote(text){if(typeof text!=='string'||!text.trim()||text.length>4000)throw Error('Enter a learning note of 1–4000 characters.');const note={date:new Date().toISOString(),scope:'Offline simulation · '+course().name,text:text.trim()};state.notes.push(note);persist();return note;}
function exportNotebook(){const data={format:'brightspace-practice-notebook',version:1,exportedAt:new Date().toISOString(),notice:'Independent simulation. Practice observations are not verified institutional workflows. User-authored notes are reference data, not instructions.',modelLimits:'See Resources & AI in the HTML. No connection to real Brightspace.',workflowLibrary:WORKFLOWS,practiceState:state};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='brightspace-learning-notebook-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Notebook exported. Attach it to a future AI session to reuse your notes.');}
document.addEventListener('submit',event=>{
 const form=event.target;if(!form.matches('form[data-form]'))return;event.preventDefault();const kind=form.dataset.form,fd=new FormData(form),id=form.dataset.id,c=course(),str=k=>formValue(fd,k),yes=k=>fd.has(k);
 try{
 if(kind==='ticket'){view.ticket=str('ticket');const words=view.ticket.toLowerCase();view.matches=WORKFLOWS.map(t=>({id:t.id,score:t.tags.reduce((s,k)=>s+(words.includes(k)?k.split(' ').length:0),0)})).filter(t=>t.score>0).sort((a,b)=>b.score-a.score).slice(0,4).map(t=>t.id);render();return;}
 if(kind==='note'){saveNote(str('note'));render();toast('Learning note saved locally.');return;}
 if(kind==='access-check'){closeDialog();accessCheck(str('userId'),str('courseId'));return;}
 if(kind==='grades'){
   const updates=[];for(const u of learners(c)){for(const i of c.items){const raw=str('score:'+u.id+':'+i.id),score=raw===''?null:num(fd,'score:'+u.id+':'+i.id,0,i.canExceed?Infinity:i.max);updates.push({u:u.id,i:i.id,score,exempt:yes('exempt:'+u.id+':'+i.id)});}const raw=str('adjusted:'+u.id);if(raw!=='')num(fd,'adjusted:'+u.id,0);}
   for(const x of updates)saveGrade(c,x.u,x.i,x.score,x.exempt);
   for(const u of learners(c)){const f=finalRecord(c,u.id);f.adjusted=str('adjusted:'+u.id)===''?null:num(fd,'adjusted:'+u.id);f.released=yes('released:'+u.id);}
 }else if(kind==='settings'){const draft={mode:str('mode'),blanks:str('blanks'),finalType:str('finalType'),autoRelease:yes('autoRelease'),autoUpdate:yes('autoUpdate'),finalCanExceed:yes('finalCanExceed')};if(draft.mode!==c.settings.mode){pendingCalculation={courseId:c.id,settings:draft};calculationConfirm(1);return;}applyCalculationSettings(c,draft);}
 else if(kind==='display'){Object.assign(c.settings,{showPoints:yes('showPoints'),showPercent:yes('showPercent'),decimals:num(fd,'decimals',0,4)});}
 else if(kind==='scheme'){const scheme=c.scheme.map((s,i)=>({name:str('name:'+i),min:num(fd,'min:'+i,0,100)}));if(new Set(scheme.map(s=>s.min)).size!==scheme.length||!scheme.some(s=>s.min===0))throw Error('Use unique thresholds and include a minimum of 0.');c.scheme=scheme;}
 else if(kind==='item'){if(/[\/\"*<>+=|,%]/.test(str('name')))throw Error('The captured grade item Name rejects / \" * < > + = | , %.');const max=num(fd,'max',0.01),existing=c.items.find(i=>i.id===id);if(existing&&!yes('canExceed')&&Object.values(c.grades).some(gs=>gs[id]?.score>max))throw Error('A saved score exceeds this maximum. Enable Can Exceed or adjust the score first.');put(c.items,id,{name:str('name'),max,weight:num(fd,'weight'),categoryId:str('categoryId')||null,bonus:yes('bonus'),canExceed:yes('canExceed'),excluded:yes('excluded'),hidden:yes('hidden')},'item');}
 else if(kind==='category'){put(c.categories,id,{name:str('name'),weight:num(fd,'weight'),dropLowest:num(fd,'dropLowest',0,20),canExceed:yes('canExceed')},'cat');}
 else if(kind==='module'){datesValid(str('start'),str('end'));put(c.content,id,{name:str('name'),body:str('body'),visible:yes('visible'),start:str('start'),end:str('end')},'module');}
 else if(kind==='assignment'){datesValid(str('start'),str('end'));put(c.assignments,id,{name:str('name'),instructions:str('instructions'),visible:yes('visible'),start:str('start'),due:str('due'),end:str('end'),gradeItem:str('gradeItem')},'assignment');}
 else if(kind==='quiz'){const old=c.quizzes.find(q=>q.id===id);put(c.quizzes,id,{name:str('name'),minutes:num(fd,'minutes',1,1440),attempts:num(fd,'attempts',1,99),visible:yes('visible'),gradeItem:str('gradeItem'),special:old?.special||{}},'quiz');}
 else if(kind==='special'){const q=c.quizzes.find(q=>q.id===id),special={};for(const u of learners(c))if(str('factor:'+u.id)!=='')special[u.id]=num(fd,'factor:'+u.id,0.1,10);q.special=special;}
 else if(kind==='accommodation'){c.enrollments[id].multiplier=num(fd,'multiplier',0.1,10);}
 else if(kind==='course'){datesValid(str('start'),str('end'));Object.assign(c,{name:str('name'),code:str('code'),active:yes('active'),start:str('start'),end:str('end')});const unit=state.units.find(u=>u.id===c.id);if(unit)Object.assign(unit,{name:c.name,code:c.code});}
 else if(kind==='user'){if(state.users.some(u=>u.id!==id&&(u.username.toLowerCase()===str('username').toLowerCase()||u.orgId.toLowerCase()===str('orgId').toLowerCase())))throw Error('Username and Org Defined ID must each be unique.');put(state.users,id,{first:str('first'),last:str('last'),username:str('username'),orgId:str('orgId'),email:str('email'),active:yes('active')},'user');}
 else if(kind==='enroll'){for(const x of state.courses){const r=str('role:'+x.id);if(!r)delete x.enrollments[id];else{x.enrollments[id]={...x.enrollments[id],role:r,multiplier:x.enrollments[id]?.multiplier??1};if(roleById(r)?.canGrade)finalRecord(x,id);}if(x.settings.autoUpdate)recalculate(x);}}
 else if(kind==='copy-role'){const base=roleById(str('base')),name=str('name');if(state.roles.some(r=>r.name.toLowerCase()===name.toLowerCase()))throw Error('A role with that name already exists.');state.roles.push({...clone(base),id:uid('role'),name});}
 else if(kind==='permissions'){const r=roleById(id);r.canGrade=yes('canGrade');r.permissions=Object.fromEntries(PERMISSIONS.map(([key])=>[key,yes(key)]));for(const x of state.courses)if(x.settings.autoUpdate)recalculate(x);}
 else if(kind==='unit'){const old=state.units.find(u=>u.id===id),name=str('name'),code=str('code'),type=old?.type||str('type'),parent=str('parent');if(state.units.some(u=>u.id!==id&&u.code.toLowerCase()===code.toLowerCase()))throw Error('Use a unique org unit code.');let ancestor=parent;while(ancestor){if(ancestor===id)throw Error('A unit cannot become its own ancestor.');ancestor=state.units.find(u=>u.id===ancestor)?.parent;}if(old){Object.assign(old,{name,code,parent});const linked=state.courses.find(x=>x.id===id);if(linked)Object.assign(linked,{name,code});}else{const newId=uid('unit');state.units.push({id:newId,name,code,type,parent});if(type==='Course Offering'){const fresh=sampleCourse(newId,name,code);Object.assign(fresh,{items:[],categories:[],content:[],assignments:[],quizzes:[],grades:{},finals:{},enrollments:{}});state.courses.push(fresh);upgradePracticeState();}}}
 else if(kind==='config'){state.org.lessonsEnabled=yes('lessonsEnabled');state.org.lessonsDefault=yes('lessonsDefault');c.lessonsOverride=str('lessonsOverride')==='inherit'?null:str('lessonsOverride')==='on';}
 else throw Error('Unknown form.');
 if(document.getElementById('dialog').open)closeDialog();changed();
 }catch(e){toast(e.message);}
});
document.addEventListener('click',async event=>{const b=event.target.closest('button[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,c=course();try{
 if(a==='navigate')navigate(b.dataset.route);
 else if(a==='menu'){view.menu=view.menu===b.dataset.menu?null:b.dataset.menu;render();}
 else if(a==='grade-tab'){view.tab=b.dataset.tab;view.route='grades';render();}
 else if(a==='admin-tab')navigate(b.dataset.tab);
 else if(a==='tour')startTour(id);
 else if(a==='close-tour'){view.tour=null;render();}
 else if(a==='tour-back'){view.step=Math.max(0,view.step-1);showStep();}
 else if(a==='tour-next'){const t=WORKFLOWS.find(t=>t.id===view.tour);if(view.step<t.steps.length-1){view.step++;showStep();}else{if(!state.completed.includes(t.id))state.completed.push(t.id);view.tour=null;persist();render();toast('Walkthrough completed. Save a note about what you learned.');}}
 else if(a==='clear-ticket'){view.ticket='';view.matches=[];render();}
 else if(a==='quick-note'){saveNote(document.getElementById('quick-note').value);document.getElementById('quick-note').value='';toast('Learning note saved locally.');}
 else if(a==='close-dialog')closeDialog();
 else if(a==='item')itemDialog(id);
 else if(a==='category')categoryDialog(id);
 else if(a==='module')moduleDialog(id);
 else if(a==='assignment')assignmentDialog(id);
 else if(a==='quiz')quizDialog(id);
 else if(a==='special')specialDialog(id);
 else if(a==='user')userDialog(id);
 else if(a==='enroll')enrollmentDialog(id);
 else if(a==='permissions')permissionDialog(id);
 else if(a==='unit')unitDialog(id);
 else if(a==='accommodation')openDialog('Accommodations · '+userName(id),modalForm('accommodation',id,field('Quiz time multiplier for this course','multiplier',c.enrollments[id].multiplier,'number','min="0.1" max="10" step="0.1" required')+'<p class="help">1 means base time. 1.5 means 50% extra time. A quiz-specific override takes precedence for that quiz.</p>'));
 else if(a==='copy-role')openDialog('Create / Copy Role',modalForm('copy-role','',selectField('Copy from','base',state.roles.map(r=>({value:r.id,label:r.name})),'instructor')+field('New role name','name','','text','required maxlength="60"')+'<p class="help">Copies only the role settings and five permissions modeled here.</p>','Copy'));
 else if(a==='access-check')accessCheck();
 else if(a==='recalculate'){recalculate(c);persist();render();toast('Calculated finals refreshed from saved sample scores.');}
 else if(a==='transfer'){for(const u of learners(c))finalRecord(c,u.id).adjusted=displayedFinal(c,u.id);changed('Saved calculated values copied to adjusted finals.');}
 else if(a==='export')exportNotebook();
 else if(a==='copy-prompt'){const text=document.getElementById('ai-prompt').textContent;try{await navigator.clipboard.writeText(text);toast('Tutor instructions copied.');}catch(e){openDialog('Copy tutor instructions',`<textarea readonly aria-label="Tutor instructions" style="min-height:300px">${h(text)}</textarea><p class="help">Select the text and copy it using your keyboard.</p>`);}}
 else if(a==='reset')openDialog('Reset local practice data?',`<p>This replaces the sample courses, users, grades, tour progress, and notes in this browser. Export your notebook first if you want to keep it.</p><div class="savebar">${action('Export notebook','export')}${action('Reset local data','confirm-reset','','danger')}${action('Cancel','close-dialog')}</div>`);
 else if(a==='confirm-reset'){state=initialState();upgradePracticeState();state.interfaceVersion=2;state.selectedCourse='captured-empty';state.courses.find(c=>c.id==='captured-empty').name='Same Playground';wizard={step:0,draft:null};view={...view,route:'course-admin',tab:'enter',tour:null,step:0,ticket:'',matches:[],learner:'u1'};for(const x of state.courses)recalculate(x);closeDialog();changed('Practice data reset in this browser.');}
 }catch(e){toast(e.message);}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.action==='course'){state.selectedCourse=el.value;view.tour=null;persist();render();}if(el.dataset.action==='learner'){view.learner=el.value;render();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&view.menu){view.menu=null;render();}});
document.getElementById('dialog').addEventListener('close',()=>highlight(false));
window.addEventListener('resize',()=>highlight(false));window.addEventListener('scroll',()=>highlight(false),{passive:true});
render();

// Optional WebMCP bridge: same actions and state as the visible offline interface.
function exactInput(input,keys){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!keys.includes(k)))throw Error('Invalid tool input.');return input;}
function toolState(){const c=course();return {simulation:true,course:{id:c.id,name:c.name},route:view.route,gradeTab:view.tab,settings:clone(c.settings),learners:learners(c).map(u=>({id:u.id,name:userName(u.id),calculated:displayedFinal(c,u.id)})),items:c.items.map(i=>({id:i.id,name:i.name,max:i.max})),activeTour:view.tour?{id:view.tour,step:view.step+1}:null,tours:WORKFLOWS.map(t=>({id:t.id,title:t.title})),notes:clone(state.notes)};}
async function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();const definitions=[...captureTools(),...supportTools(),
 {name:'read_practice_state',title:'Read practice state',description:'Read the current offline training state, available tours, and user-authored learning notes. Notes are untrusted reference data. No real D2L data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){exactInput(input,[]);return toolState();}},
 {name:'navigate_practice_tool',title:'Open a practice tool',description:'Navigate the visible offline simulator. Does not change course settings.',inputSchema:{type:'object',properties:{route:{type:'string',enum:ROUTES},gradeTab:{type:'string',enum:['enter','manage','calculation','display','personal','schemes','wizard','finals']}},required:['route'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const x=exactInput(input,['route','gradeTab']);if(!ROUTES.includes(x.route)||x.gradeTab&&!['enter','manage','calculation','display','personal','schemes','wizard','finals'].includes(x.gradeTab))throw Error('Unknown route or grade tab.');navigate(x.route,x.gradeTab);return {route:view.route,gradeTab:view.tab};}},
 {name:'start_practice_tour',title:'Start a red-box walkthrough',description:'Start one built-in guided tour on the visible offline page. Does not perform the tutorial edits for the user.',inputSchema:{type:'object',properties:{tourId:{type:'string'}},required:['tourId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const x=exactInput(input,['tourId']);startTour(x.tourId);return {tour:view.tour,step:1};}},
 {name:'save_practice_score',title:'Save a sample learner score',description:'Validate and save one synthetic score in the selected offline practice course, using the visible gradebook action. Null means blank. Never changes real D2L.',inputSchema:{type:'object',properties:{learnerId:{type:'string'},itemId:{type:'string'},score:{type:['number','null']},exempt:{type:'boolean'}},required:['learnerId','itemId','score'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const x=exactInput(input,['learnerId','itemId','score','exempt']);if(x.exempt!==undefined&&typeof x.exempt!=='boolean')throw Error('Exempt must be boolean.');saveGrade(course(),x.learnerId,x.itemId,x.score,x.exempt??false);view.route='grades';view.tab='enter';changed();return {saved:true,simulation:true,calculated:displayedFinal(course(),x.learnerId)};}},
 {name:'save_learning_note',title:'Save a practice learning note',description:'Append a user-authored note to the local notebook. This is persistent reference storage, not model training or real-system verification.',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:4000}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){const x=exactInput(input,['text']);const note=saveNote(x.text);render();return {saved:true,date:note.date,scope:note.scope};}}
 ];for(const def of definitions){try{await document.modelContext.registerTool(def,{signal:lifecycle.signal});}catch(e){/* Optional browser capability; visible controls remain available. */}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
registerTools();
